def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)
    tests = [fmt(['pop']), fmt(['add 1', 'pop']), fmt(['add 1000000000', 'pop', 'pop']),
             fmt(['pop', 'pop', 'pop', 'add 2', 'add 2', 'add 3', 'pop', 'pop', 'pop']),
             fmt(['pop', 'add 1', 'add 1', 'pop', 'pop'])]
    for q in (3, 6, 10, 15, 20, 30):
        for _ in range(3):
            ops = []
            mx = 0
            for _ in range(q):
                if rng.random() < 0.55:
                    ops.append('pop')
                    mx += 1
                else:
                    ops.append('add ' + str(rng.randint(1, mx + 3)))
            tests.append(fmt(ops))
    def big(pop_p, spread):
        ops = []
        mx = 0
        for _ in range(100000):
            if rng.random() < pop_p:
                ops.append('pop')
                mx += 1
            else:
                r = rng.random()
                if r < 0.05:
                    ops.append('add ' + str(rng.randint(1, 10**9)))
                else:
                    ops.append('add ' + str(rng.randint(max(1, mx - spread), mx + 2)))
        return fmt(ops)
    tests.append(big(0.6, 100000))
    tests.append(big(0.5, 50))
    tests.append(big(0.9, 100000))
    tests.append(fmt(['pop'] * 100000))
    return tests

